aarbare gebeurtenissen, die anderen aan een stille kracht toeschrijven, neemt hij aanvankelijk niet serieus. Na een conflict met een regent dringen die verschijnselen zijn eigen huis binnen. Tegelijk staan zijn familierelaties onder druk. Couperus laat zien hoe de zekerheid van een koloniale bestuurder steeds verder wordt aangetast.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/341595/de-stille-kracht.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/341595/de-stille-kracht.html","sha256":"3f226e62ae7edc9482a529cfdba59ffb45d5f18f6dc9611c0d7266211e44ff20","checkedAt":"2026-11-01T20:44:06.896Z","fact":"Hardback ISBN 9789025306601 verschijningsdatum 12/07/2001 NUR 301 Literaire roman, novelle uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Louis Couperus"},{"url":"https://metadata.isbn.nl/341595/de-stille-kracht.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789041716712","key":{"isbn_13":"9789041716712"},"before":null,"after":{"work_id":1197,"title":"De kleine Johannes","language":"nld","isbn_13":"9789041716712","isbn_10":null,"open_library_edition_id":null,"publisher":"Rainbow"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789041716712","key":{"edition_id":"@edition:9789041716712"},"before":null,"after":{"edition_id":"@edition:9789041716712","work_id":1197,"bound_author_id":701,"bound_title":"De kleine Johannes","bound_language":"nld","bound_isbn13":"9789041716712","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000717849_De_kleine_Johannes_0_0.jpg","card_cover_url":null,"evidence_url":"https://metada