 uitgroeien tot iets waaraan een mens niet ontsnapt.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/286137/de-koperen-tuin.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/286137/de-koperen-tuin.html","sha256":"11d4edbc74822222467dbb2cb97b11f67ffbc09151b00d6d785c99929b7c23e6","checkedAt":"2026-11-01T20:41:36.135Z","fact":"Paperback ISBN 9789038803630 verschijningsdatum 25/10/2016 NUR 301 Literaire roman, novelle imprint Nijgh & Van Ditmar uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Simon Vestdijk"},{"url":"https://metadata.isbn.nl/286137/de-koperen-tuin.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789049804916","key":{"isbn_13":"9789049804916"},"before":null,"after":{"work_id":1207,"title":"De tienduizend dingen","language":"nld","isbn_13":"9789049804916","isbn_10":null,"open_library_edition_id":null,"publisher":"Dwarsligger®"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789049804916","key":{"edition_id":"@edition:9789049804916"},"before":null,"after":{"edition_id":"@edition:9789049804916","work_id":1207,"bound_author_id":706,"bound_title":"De tienduizend dingen","bound_language":"nld","bound_isbn13":"9789049804916","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000184718_De_tienduizend_dingen_2_710_130_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/754410/de-tienduizend-dingen.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/754410/de-tienduizend-dingen