ublisher","source_name":"Uitgever/auteur; oorspronkelijke gecontroleerde samenvatting","source_url":"https://www.singeluitgeverijen.nl/athenaeum/boek/dwaallicht/","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/341636/het-dwaallicht.html","sha256":"e1f5623d807da6556466d931552c8ce3378d01c7fd78a7b72cac774aab7cd984","checkedAt":"2026-11-01T20:44:11.240Z","fact":"Paperback ISBN 9789025367664 verschijningsdatum 01/05/2010 NUR 301 Literaire roman, novelle uitgever Singel Uitgeverijen taal Nederlands","sourceAuthors":"Willem Elsschot , Eric Rinckhout"},{"url":"https://www.singeluitgeverijen.nl/athenaeum/boek/dwaallicht/","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789045124001","key":{"isbn_13":"9789045124001"},"before":null,"after":{"work_id":1254,"title":"Het boek van alle dingen","language":"nld","isbn_13":"9789045124001","isbn_10":null,"open_library_edition_id":null,"publisher":"Querido"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789045124001","key":{"edition_id":"@edition:9789045124001"},"before":null,"after":{"edition_id":"@edition:9789045124001","work_id":1254,"bound_author_id":673,"bound_title":"Het boek van alle dingen","bound_language":"nld","bound_isbn13":"9789045124001","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000307361_Het_boek_van_alle_dingen_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/454163/het-boek-van-alle-dingen.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/454163/het-boek-van-alle-dingen.html","sha256":"3ff2583e05809ee4abb11ed299a1a0d365bf0dd01b94cd1bdecac1ebde7