agelijks leven bepalen. Onderwijs en medische zorg zijn niet vanzelfsprekend. Door zichzelf te scholen weet ze uiteindelijk een universiteit binnen te komen. Haar herinneringen volgen hoe een nieuwe wereld haar mogelijkheden vergroot, maar ook vragen oproept over geweld, loyaliteit en haar verhouding tot haar familie.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/1055565/leerschool.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-03-20261101","evidence":[{"url":"https://metadata.isbn.nl/1055565/leerschool.html","sha256":"72357be03f1d7b428598e385d2e11919b942ab506f6dcf94bbb7522cc7a9a707","checkedAt":"2026-11-01T20:41:45.258Z","fact":"Paperback ISBN 9789403166100 verschijningsdatum 13/06/2019 NUR 320 Literaire non-fictie algemeen uitgever Bezige Bij b.v., Uitgeverij De taal Nederlands","sourceAuthors":"Tara Westover"},{"url":"https://metadata.isbn.nl/1055565/leerschool.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789048847389","key":{"isbn_13":"9789048847389"},"before":null,"after":{"work_id":83,"title":"Mijn verhaal","language":"nld","isbn_13":"9789048847389","isbn_10":null,"open_library_edition_id":null,"publisher":"Hollands Diep"}},{"relation":"catalog_edition_metadata","ref":"metadata:9789048847389","key":{"edition_id":"@edition:9789048847389"},"before":null,"after":{"edition_id":"@edition:9789048847389","work_id":83,"bound_author_id":70,"bound_title":"Mijn verhaal","bound_language":"nld","bound_isbn13":"9789048847389","format":"hardcover","cover_url":"https://metadata.isbn.nl/ie_fcache/0000286672_Mijn_verhaal_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/1127824/mijn-verhaal